mapper.select:
select purchase_demand.*, user.name as buyerName, category.name as categoryName from purchase_demand
left join user on purchase_demand.buyer_id = user.id
left join category on purchase_demand.category_id = category.id

     and purchase_demand.product_name like concat('%', #{productName}, '%')
     and purchase_demand.category_id = #{categoryId}
     and purchase_demand.buyer_id = #{buyerId}
     and purchase_demand.status = #{status}

order by purchase_demand.id desc

mapper.update:
update purchase_demand set buyer_id = #{buyerId}, product_name = #{productName}, category_id = #{categoryId},
total_quantity = #{totalQuantity}, quantity = #{quantity}, unit = #{unit}, expected_price = #{expectedPrice}, receive_area = #{receiveArea}, deadline = #{deadline},
contact = #{contact}, status = #{status}, create_time = #{createTime}
where id = #{id}
